<template><div class="auth-page"><section class="auth-card"><h1>Check your email</h1><p>We sent a verification link to <strong>{{ email || 'your email address' }}</strong>.</p><button class="primary" :disabled="busy" @click="resend">{{ busy?'Sending…':'Resend verification email' }}</button><p v-if="message" class="notice">{{ message }}</p><router-link to="/login">Back to sign in</router-link></section></div></template>
<script setup lang="ts">import{ref}from'vue';import{useRoute}from'vue-router';import{resendVerification}from'@/api/auth';const route=useRoute(),email=String(route.query.email||''),busy=ref(false),message=ref('');async function resend(){if(!email)return;busy.value=true;try{await resendVerification(email);message.value='If the account exists, a verification email has been sent.'}finally{busy.value=false}}</script>
<style scoped>.auth-page{display:grid;place-items:center;min-height:60vh}.auth-card{width:min(400px,100%);border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:2rem;text-align:center}.primary{display:block;width:100%;margin:1.5rem 0;padding:.8rem;background:var(--color-primary);color:white;border:0;border-radius:var(--radius-md)}.notice{color:#16794a}</style>
